export function filterProductionStations(query="",stage:ProductionStage|"all"="all",status:"all"|"available"|"working"|"partial"|"planned"="all"){const terms=query.trim().toLowerCase().split(/\s+/).filter(Boolean);return PRODUCTION_STATIONS.filter(s=>(stage==="all"||s.stage===stage)&&(status==="all"||(status==="available"?s.status!=="planned":status==="working"?s.status==="available":s.status===status))&&terms.every(term=>[s.name,s.function,s.dependencies,s.manualPredecessor,s.measure,s.roleId,s.workingNow||"",s.remaining||""].join(" ").toLowerCase().includes(term)));}

/** Counts describe audited functions, never extra implemented buildings. */
export function stationCatalogueCounts(){return{total:PRODUCTION_STATIONS.length,working:PRODUCTION_STATIONS.filter(s=>s.status==="available").length,partial:PRODUCTION_STATIONS.filter(s=>s.status==="partial").length,planned:PRODUCTION_STATIONS.filter(s=>s.status==="planned").length};}
